p='src/main/java/net/officefloor/hq/app/invoices/Invoice.java'
s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
rep('''    /** The most a plan's down payment can be, a percentage of the grand total. */''','''    /** The most a draft's surcharge can be, a percentage of its amount after its discounts. */
    public static final BigDecimal MAX_SURCHARGE_PCT = new BigDecimal("25");

    /** The most a plan's down payment can be, a percentage of the grand total. */''')
rep('''    @Column(name = "retention_pct")
    private BigDecimal retentionPct = BigDecimal.ZERO;
''','''    @Column(name = "retention_pct")
    private BigDecimal retentionPct = BigDecimal.ZERO;

    /** The rush surcharge, a percentage of the amount after the discounts, 0 to {@link #MAX_SURCHARGE_PCT}. */
    @Column(name = "surcharge_pct")
    private BigDecimal surchargePct = BigDecimal.ZERO;
''')
rep('''        copy.retentionPct = retentionPct;
''','''        copy.retentionPct = retentionPct;
        copy.surchargePct = surchargePct;
''')
rep('''    /** The percentage of the amount before tax held back as retention, 0 to {@link #MAX_RETENTION_PCT}. */''','''    /** The rush surcharge, a percentage of the amount after the discounts, 0 to {@link #MAX_SURCHARGE_PCT}. */
    public BigDecimal getSurchargePct() {
        return surchargePct;
    }

    /** Sets the rush surcharge percentage; it has already been checked. */
    public void setSurchargePct(BigDecimal surchargePct) {
        this.surchargePct = surchargePct;
    }

    /** The percentage of the amount before tax held back as retention, 0 to {@link #MAX_RETENTION_PCT}. */''')
rep('''     * The minimum charge's exact tax at the client's rate follows, as one more line.''','''     * The exact tax of the surcharge and minimum charge at the client's rate follows, as one more line.''')
rep('''taxes.add(isReverseCharge() ? BigDecimal.ZERO : minimumCharge().multiply(clientRate).movePointLeft(2));''','''taxes.add(isReverseCharge() ? BigDecimal.ZERO : surcharge().add(minimumCharge()).multiply(clientRate).movePointLeft(2));''')
rep('''     * to the invoice tax, less the minimum charge's share,''','''     * to the invoice tax, less the share of the surcharge and minimum charge,''')
rep('''     * shares and the minimum charge, less''','''     * shares, the surcharge and the minimum charge, less''')
rep('''            taxed = taxed.add(minimumCharge());''','''            taxed = taxed.add(surcharge()).add(minimumCharge());''')
rep('''            // The minimum charge keeps its own tax, which is not a line's.
            BigDecimal minimum = minimumCharge();''','''            // The surcharge and minimum charge keep their own tax, which is not a line's.
            BigDecimal minimum = surcharge().add(minimumCharge());''')
rep('''    /**
     * The minimum charge: what the subtotal less the discount falls short of the workspace's minimum''','''    /** The amount after the discounts: the subtotal less the discount. */
    public BigDecimal discounted() {
        return subtotal().subtract(discount());
    }

    /**
     * The rush surcharge: the surcharge percentage of the amount after the discounts, rounded down to
     * the cent. It is not discounted and is taxed at the client's rate. Nothing for a credit note.
     */
    public BigDecimal surcharge() {
        if (isCreditNote()) {
            return zero();
        }
        return discounted().multiply(surchargePct).movePointLeft(2).setScale(scale(), RoundingMode.DOWN);
    }

    /**
     * The minimum charge: what the subtotal less the discount plus the surcharge falls short of the workspace's minimum''')
rep('''        return minimum.subtract(subtotal().subtract(discount())).max(zero());''','''        return minimum.subtract(discounted().add(surcharge())).max(zero());''')
rep('''     * The amount before tax: the subtotal less the discount plus the minimum charge, less''','''     * The amount before tax: the subtotal less the discount plus the surcharge and the minimum charge, less''')
rep('''     * The grand total: the subtotal less the discount plus the minimum charge, plus''','''     * The grand total: the subtotal less the discount plus the surcharge and the minimum charge, plus''')
s=s.replace('''        BigDecimal amount = subtotal().subtract(discount()).add(minimumCharge());''','''        BigDecimal amount = discounted().add(surcharge()).add(minimumCharge());''')
open(p,'w').write(s)
EOF
